// The machine at the back of the health monitoring system.
// Idea and logic: the human member of team "Just For Fun", NASA Space Apps Challenge 2026.
// Code generated by Claude (Anthropic), an AI system, from the team's description.
//
// The logic, as the team described it:
// - All readings go into one machine and are sorted into cells.
// - Number cells (the team's A and B, and every other clearly numeric result) compare the number
//   with the norm. Within the norm: the AI is not triggered. Outside the norm: the AI is triggered
//   and takes over. A blood test panel is a set of numbers, each compared with its own norm.
// - Complex cells (the team's C, for example an X-ray) cannot be checked by comparing a number.
//   They need analysis by the AI or by a doctor; the AI may call the doctor.
// - The camera has triggers: a sleeping person is ignored; a person who grabs their chest
//   triggers the automation, which calls the doctor on Earth if there is no doctor on board.
// - Daily self-reports about the psyche are recorded; the AI reviews them periodically
//   (for example every two weeks) and warns the person if their spirit is dropping.
// Anything the team has not decided yet is returned as an open question, never guessed.
// One exception, drafted by Claude after NASA-style reviews (15 Nov 2026) and marked as a draft for the team:
// a reading past a published red limit (config.js, "red") goes to the crew on board at once by automation,
// without the AI, and the doctor's message is queued when there is no link. "Undecided" is never the answer there.

export const KIND = Object.freeze({
  NUMBER: 'number',
  PANEL: 'panel', // a set of numbers, each with its own norm (blood tests)
  COMPLEX: 'complex',
  CAMERA: 'camera',
  SELF: 'self-report', // recorded, reviewed later; no norm of its own
});

export const STATUS = Object.freeze({
  OK: 'ok', // within the norm
  OUT: 'out', // outside the norm, or a camera alarm
  ANALYSIS: 'analysis', // needs analysis
  IGNORED: 'ignored', // camera saw something it must not react to
  RECORDED: 'recorded', // stored for later review
  UNKNOWN: 'unknown', // no cell, no trigger, or a value the machine cannot read
  EMPTY: 'empty', // a periodic review with nothing to review
});

export const DEST = Object.freeze({
  NONE: 'none', // stays in the machine, nobody is called
  AI: 'ai',
  DOCTOR_ONBOARD: 'doctor-onboard',
  DOCTOR_EARTH: 'doctor-earth',
  // The automation alerts the person and the crew on board (the crew medical officer), and calls the doctor or
  // queues the doctor's message (store-and-forward) when there is no link. Draft, for the team to confirm.
  CREW_ALARM: 'crew-alarm',
  UNDECIDED: 'undecided', // the team has not decided yet who takes it
});

// Open questions the team still has to answer. Step codes point to them.
export const OPEN_QUESTION = Object.freeze({
  AI_NEXT: 1, // what the AI does with an out-of-norm reading, and when it calls a doctor
  DIRECT_ALARM: 2, // which out-of-norm readings call the doctor at once, by automation, without the AI
  COMPLEX_WHO: 3, // complex data: when the AI analyzes it and when a doctor does
  AI_DOWN: 4, // the AI stopped working: can the automation carry the work
  NO_DOCTOR_NO_LINK: 5, // no doctor on board and no link to Earth
  ADVICE: 6, // what advice and help the person gets
  WHICH_NORM: 7, // which of the four norms each cell compares with
  PSYCH_RULE: 8, // which questionnaire, and by what rule the AI decides the spirit is dropping
});

// Strict number reading: only real numbers or non-blank numeric strings count.
// null, false, [] or ' ' must never turn into 0.
function toNum(x) {
  if (typeof x === 'number') return x;
  if (typeof x === 'string' && x.trim() !== '') return Number(x);
  return NaN;
}

const has = (x) => x !== null && x !== undefined;

// Compares one reading with the cell's norm.
// Returns { valid: false } when the value cannot be read,
// otherwise { valid: true, inNorm, side } where side is 'below', 'above' or null.
// context (optional): { baseline, baselineTime }, the person's own pre-flight test of a measure judged by its shift
// from it (norm type 'baseline-shift', hearing); the machine finds it (receive below).
export function checkNorm(cell, value, profile, context = null) {
  const n = cell.norm || {};
  if (cell.normType === 'baseline-shift') {
    // NASA's rule for hearing: a shift of shiftAtLeast or more from the person's own pre-flight test counts. With no
    // pre-flight test on record, the cell's second reference (an absolute value, WHO's 20 dB) stands in. Drafts.
    const v = toNum(value);
    if (!Number.isFinite(v) || (v < 0 && !cell.allowNegative)) return { valid: false };
    const base = context && Number.isFinite(context.baseline) ? context.baseline : null;
    if (base === null) {
      const f = n.fallback || {};
      const out = has(f.max) && (f.maxExclusive ? v >= f.max : v > f.max);
      return { valid: true, inNorm: !out, side: out ? 'above' : null, norm: 'earthGeneral' };
    }
    const shift = Math.round((v - base) * 10) / 10;
    const inNorm = shift < n.shiftAtLeast;
    return { valid: true, inNorm, side: inNorm ? null : 'above', shift, baseline: base, baselineTime: context.baselineTime || null };
  }
  if (cell.normType === 'range') {
    const v = toNum(value);
    // Below zero is a device error for body readings, radiation or CO2; a cell where it is
    // physically real (cabin temperature in degrees C) says so with allowNegative.
    if (!Number.isFinite(v) || (v < 0 && !cell.allowNegative)) return { valid: false };
    // A lower limit that differs by sex (for example NASA's daily fluid need); with the sex unknown,
    // the lower of the two is used, so nobody is flagged by the stricter one by mistake.
    const sexMin = n.minBySex ? (n.minBySex[profile && profile.sex] ?? Math.min(...Object.values(n.minBySex))) : null;
    if (sexMin !== null && v < sexMin) return { valid: true, inNorm: false, side: 'below' };
    if (has(n.min) && v < n.min) return { valid: true, inNorm: false, side: 'below' };
    if (has(n.max) && (n.maxExclusive ? v >= n.max : v > n.max)) return { valid: true, inNorm: false, side: 'above' };
    return { valid: true, inNorm: true, side: null };
  }
  if (cell.normType === 'below-both') {
    // Blood pressure: the norm is both numbers below their limits.
    // There is no lower limit yet (no verified source); in-norm entries say so as an open step.
    const sys = toNum(value ? value.sys : undefined);
    const dia = toNum(value ? value.dia : undefined);
    if (!Number.isFinite(sys) || !Number.isFinite(dia) || sys <= 0 || dia <= 0) return { valid: false };
    if ((has(n.sysMin) && sys < n.sysMin) || (has(n.diaMin) && dia < n.diaMin)) return { valid: true, inNorm: false, side: 'below' };
    const inNorm = sys < n.sysBelow && dia < n.diaBelow;
    return { valid: true, inNorm, side: inNorm ? null : 'above' };
  }
  if (cell.normType === 'min-parts') {
    // Several numbers that must each stay at or above their own minimum (bone density sites).
    let inNorm = true;
    for (const part of n.parts) {
      const v = toNum(value ? value[part.key] : undefined);
      if (!Number.isFinite(v) || v < 0) return { valid: false };
      if (v < part.min) inNorm = false;
    }
    return { valid: true, inNorm, side: inNorm ? null : 'below' };
  }
  if (cell.normType === 'record') {
    // A measure with no checked norm (for example exercise minutes): it is recorded, never judged.
    // Below zero is a device or typing error here too (minus 5 minutes of exercise), unless the cell allows it.
    const v = toNum(value);
    if (!Number.isFinite(v) || (v < 0 && !cell.allowNegative)) return { valid: false };
    return { valid: true, inNorm: null, side: null };
  }
  if (cell.normType === 'baseline-percent') {
    // NASA's rule: in flight, stay at or above a share of the person's own pre-flight level.
    const v = toNum(value);
    const base = profile && profile.baselines ? toNum(profile.baselines[cell.baselineKey]) : NaN;
    if (!Number.isFinite(v) || v < 0) return { valid: false };
    if (!Number.isFinite(base) || base <= 0) return { valid: false, reason: 'no-baseline' };
    const percent = (v / base) * 100;
    const inNorm = percent >= n.minPercent;
    return { valid: true, inNorm, side: inNorm ? null : 'below', percent };
  }
  return { valid: false };
}

// The most severe red limit a reading is past, or null (config.js, "red": published single values, drafts).
// One reading is enough: no streak. A limit marked atRest is skipped for a reading taken during exercise.
const RED_RANK = { action: 1, urgent: 2 };
export function redLimitOf(cell, value, reading = null) {
  const limits = cell && Array.isArray(cell.red) ? cell.red : [];
  const exercising = Boolean(reading && reading.context === 'exercise');
  let hit = null;
  for (const lim of limits) {
    if (lim.atRest && exercising) continue;
    const v = toNum(lim.part ? (value ? value[lim.part] : undefined) : value);
    if (!Number.isFinite(v)) continue;
    const past = lim.when === 'below' ? v < lim.value
      : lim.when === 'atOrBelow' ? v <= lim.value
        : lim.when === 'above' ? v > lim.value
          : lim.when === 'atOrAbove' ? v >= lim.value : false;
    if (past && (!hit || RED_RANK[lim.level] > RED_RANK[hit.level])) hit = lim;
  }
  return hit;
}

// Checks each value of a panel against its own range. Values or ranges that are not numbers are skipped.
export function checkPanel(value) {
  const analytes = value && Array.isArray(value.analytes) ? value.analytes : [];
  const out = [];
  let checked = 0;
  for (const a of analytes) {
    const v = toNum(a.value);
    if (!Number.isFinite(v)) continue;
    const min = has(a.min) ? toNum(a.min) : NaN;
    const max = has(a.max) ? toNum(a.max) : NaN;
    if (!Number.isFinite(min) && !Number.isFinite(max)) continue;
    checked += 1;
    if (Number.isFinite(min) && v < min) out.push({ ...a, side: 'below' });
    else if (Number.isFinite(max) && v > max) out.push({ ...a, side: 'above' });
  }
  if (checked === 0) return { valid: false };
  return { valid: true, inNorm: out.length === 0, checked, out };
}

// Nothing, an empty string or a string of only spaces counts as empty.
const isBlank = (v) => v === null || v === undefined || (typeof v === 'string' && v.trim() === '');

// A self-report on a fixed scale (for example sleep quality from 1 to 7) must be a number on that scale.
function onScale(cell, value) {
  if (!cell.scale) return true;
  // A cell may read its own value (the energy question: whole steps, and the old words "energetic" and "sluggish").
  const v = typeof cell.step === 'function' ? cell.step(value) : toNum(value);
  return Number.isFinite(v) && v >= cell.scale.min && v <= cell.scale.max;
}

// A self-report from a fixed list must be on that list, so a typo never counts as a real answer: one of the
// cell's answers (the eye self-check), a symptom from its list with a whole number on its scale, or a medicine
// from its kit list (or "other" with a name) with an amount above zero. The lists live in config.js.
function onList(cell, value) {
  if (cell.answers) return cell.answers.some((a) => a.value === value);
  const entry = value !== null && typeof value === 'object' && !Array.isArray(value);
  if (cell.symptoms) {
    const s = cell.severity || {};
    return entry && cell.symptoms.some((x) => x.key === value.symptom)
      && Number.isInteger(value.severity) && value.severity >= s.min && value.severity <= s.max;
  }
  if (cell.kit) {
    const named = entry && (cell.kit.some((k) => k.key === value.medicine)
      || (value.medicine === 'other' && typeof value.name === 'string' && value.name.trim() !== ''));
    return Boolean(named) && typeof value.amount === 'number' && Number.isFinite(value.amount) && value.amount > 0;
  }
  return true;
}

// Can the machine read this self-report? Not empty, on its scale, on its list. The server can use the same check.
export function checkSelf(cell, value) {
  return { valid: !isBlank(value) && onScale(cell, value) && onList(cell, value) };
}

// Every reading is signed with the person it belongs to (reading.person). Each person has their
// own pre-flight levels, their own history and their own pile for the periodic review, so data of
// different people never mix. A reading without a known person is not accepted.
// mission (optional): { launch }, so a reading can be told apart as before or after launch; a measure judged by its
// shift from the person's own pre-flight test (hearing) needs it. Without a mission no reading counts as pre-flight.
export function createMachine({ cells, crew = [], state = {}, now = () => new Date(), mission = null } = {}) {
  if (!Array.isArray(cells)) throw new TypeError('cells must be an array');
  if (!Array.isArray(crew)) throw new TypeError('crew must be an array');
  const s = { aiWorks: true, doctorOnBoard: false, linkToEarth: true, ...state };
  const launchMs = mission && mission.launch ? new Date(mission.launch).getTime() : NaN;
  const byIndicator = new Map(cells.map((c) => [c.indicator, c]));
  const people = new Map(crew.map((p) => [p.id, p]));
  let seq = 0;
  const piles = new Map(); // person id -> what waits for that person's periodic review
  const history = new Map(); // person id + indicator -> readings in time order
  const pileOf = (id) => { if (!piles.has(id)) piles.set(id, []); return piles.get(id); };
  const hkey = (id, indicator) => `${id}${indicator}`;
  // A reading may carry its own time (stored or imported data); otherwise it happens now.
  const timeOf = (t) => { const d = t ? new Date(t) : null; return d && Number.isFinite(d.getTime()) ? d : now(); };
  // The person's own pre-flight test of a measure: the latest reading of it before launch (a draft: NASA compares
  // with "preflight audiometric tests"), for a reading taken at or after launch. null before launch, or with no mission.
  function preflightOf(personId, indicator, time) {
    if (!Number.isFinite(launchMs) || time.getTime() < launchMs) return null;
    const before = (history.get(hkey(personId, indicator)) || []).filter((x) => x.time.getTime() < launchMs && Number.isFinite(toNum(x.value)));
    const last = before[before.length - 1];
    return last ? { baseline: toNum(last.value), baselineTime: last.time.toISOString() } : null;
  }
  // The shift from the pre-flight test travels with the steps and the history, for the screens and the levels.
  const shiftOf = (r) => (r.shift !== undefined ? { shift: r.shift, baseline: r.baseline, baselineTime: r.baselineTime } : {});

  // The camera path, in the team's words: the automation calls the doctor on Earth
  // if there is no doctor on board. No doctor and no link was an open question; the draft default now is the
  // crew on board, with the doctor's message queued until the link returns (for the team to confirm).
  function callDoctor(steps) {
    if (s.doctorOnBoard) {
      steps.push({ code: 'to-doctor-onboard', by: 'doctor' });
      return DEST.DOCTOR_ONBOARD;
    }
    if (s.linkToEarth) {
      steps.push({ code: 'to-doctor-earth', by: 'doctor' });
      return DEST.DOCTOR_EARTH;
    }
    steps.push({ code: 'no-doctor-crew', by: 'machine', question: OPEN_QUESTION.NO_DOCTOR_NO_LINK, draft: true });
    steps.push({ code: 'alarm-crew', by: 'machine', level: 'urgent' });
    steps.push({ code: 'doctor-queued', by: 'machine' });
    return DEST.CREW_ALARM;
  }

  // Past a red limit, by automation alone (never the AI): the person and the crew on board are alerted, then the
  // doctor: on board, on Earth over the link, or a queued message when there is no link (store-and-forward).
  // Why the crew first: NASA requires means of autonomous medical care (NASA-STD-3001 Vol 1 Rev C [V1 3004],
  // https://www.nasa.gov/wp-content/uploads/2023/11/nasa-std-3001-vol-1-rev-c-with-signature.pdf), and in the ISS
  // medical event of January 2026 crewmates gave the first, immediate help
  // (https://www.nasa.gov/blogs/commercialcrew/2026/02/25/nasas-spacex-crew-11-astronaut-update/).
  function crewAlarm(steps, level) {
    steps.push({ code: 'alarm-person', by: 'machine', level });
    steps.push({ code: level === 'urgent' ? 'alarm-crew' : 'alarm-cmo', by: 'machine', level });
    if (s.doctorOnBoard) steps.push({ code: 'to-doctor-onboard', by: 'doctor' });
    else if (s.linkToEarth) steps.push({ code: 'to-doctor-earth', by: 'doctor' });
    else steps.push({ code: 'doctor-queued', by: 'machine' });
    return DEST.CREW_ALARM;
  }

  // A cabin value past the ship's own limit is the ship's alarm: every crew screen shows it at the ship's level,
  // and the ship's procedures lead (NASA-STD-3001 Vol 2 Rev F [V2 6022] and Table 10.3-1,
  // https://standards.nasa.gov/system/files/tmp/NASA-STD-3001%20Vol%202%20Rev%20F.pdf). No doctor is called for the air.
  function redAlarm(steps, red, cell) {
    steps.push({ code: 'red-limit', by: 'machine', level: red.level, limit: red, question: OPEN_QUESTION.DIRECT_ALARM, draft: true });
    if (cell.section === 'env') {
      steps.push({ code: 'ship-alarm', by: 'machine', level: red.level });
      return DEST.CREW_ALARM;
    }
    return crewAlarm(steps, red.level);
  }

  // Outside the norm, in the team's words: the AI is triggered and takes over.
  function outOfNorm(steps) {
    if (s.aiWorks) {
      steps.push({ code: 'ai-takes', by: 'ai' });
      steps.push({ code: 'ai-next-open', by: 'open', question: OPEN_QUESTION.AI_NEXT });
      steps.push({ code: 'direct-alarm-open', by: 'open', question: OPEN_QUESTION.DIRECT_ALARM });
      return DEST.AI;
    }
    steps.push({ code: 'ai-down-open', by: 'open', question: OPEN_QUESTION.AI_DOWN });
    steps.push({ code: 'direct-alarm-open', by: 'open', question: OPEN_QUESTION.DIRECT_ALARM });
    return DEST.UNDECIDED;
  }

  function entry(reading, cell, status, dest, steps, person = null, time = null) {
    seq += 1;
    return {
      id: seq,
      time: time || now(),
      person,
      reading,
      cellId: cell ? cell.id : null,
      indicator: reading ? reading.indicator : null,
      status,
      dest,
      steps,
      state: { ...s },
    };
  }

  function receive(reading) {
    const steps = [];
    const person = reading && people.has(reading.person) ? people.get(reading.person) : null;
    const time = timeOf(reading ? reading.time : null);
    if (!person) {
      steps.push({ code: 'no-person', by: 'machine' });
      return entry(reading, null, STATUS.UNKNOWN, DEST.UNDECIDED, steps, null, time);
    }
    const profile = person;
    const selfReports = pileOf(person.id);
    const cell = byIndicator.get(reading.indicator);
    let status;
    let dest;
    let red = null;

    if (!cell) {
      steps.push({ code: 'no-cell', by: 'machine' });
      status = STATUS.UNKNOWN;
      dest = DEST.UNDECIDED;
    } else if (cell.kind === KIND.NUMBER) {
      const r = checkNorm(cell, reading.value, profile, cell.normType === 'baseline-shift' ? preflightOf(person.id, cell.indicator, time) : null);
      if (!r.valid) {
        steps.push({ code: r.reason === 'no-baseline' ? 'no-baseline' : 'bad-value', by: 'machine' });
        status = STATUS.UNKNOWN;
        dest = DEST.UNDECIDED;
      } else {
        // Red limits lie outside the norm, so only a reading outside the norm is checked against them.
        red = r.inNorm === false ? redLimitOf(cell, reading.value, reading) : null;
        if (r.inNorm === null) {
          steps.push({ code: 'no-norm-recorded', by: 'machine' });
          status = STATUS.RECORDED;
          dest = DEST.NONE;
        } else if (cell.atRest && reading.context === 'exercise' && !red) {
          // A norm for rest says nothing about a reading taken during exercise: it is recorded, not judged (draft).
          steps.push({ code: 'exercise-recorded', by: 'machine' });
          status = STATUS.RECORDED;
          dest = DEST.NONE;
        } else {
        steps.push({ code: 'norm-used', by: 'machine', norm: r.norm || cell.compareWith, question: OPEN_QUESTION.WHICH_NORM });
        if (r.inNorm) {
          steps.push({ code: 'in-norm', by: 'machine', percent: r.percent, ...shiftOf(r) });
          if (cell.normType === 'below-both' && !has(cell.norm.sysMin)) steps.push({ code: 'no-lower-limit', by: 'open' });
          status = STATUS.OK;
          dest = DEST.NONE;
        } else {
          steps.push({ code: 'out-of-norm', by: 'machine', side: r.side, percent: r.percent, ...shiftOf(r) });
          status = STATUS.OUT;
          dest = red ? redAlarm(steps, red, cell) : outOfNorm(steps);
        }
        }
        // In the team's words, hours of sleep are part of the daily report the AI reviews later.
        if (cell.reviewByAi) {
          selfReports.push({ indicator: cell.indicator, value: reading.value, time });
          steps.push({ code: 'psych-review-later', by: 'machine' });
        }
      }
    } else if (cell.kind === KIND.PANEL) {
      const r = checkPanel(reading.value);
      if (!r.valid) {
        steps.push({ code: 'bad-value', by: 'machine' });
        status = STATUS.UNKNOWN;
        dest = DEST.UNDECIDED;
      } else {
        steps.push({ code: 'norm-used', by: 'machine', norm: cell.compareWith, question: OPEN_QUESTION.WHICH_NORM });
        if (r.inNorm) {
          steps.push({ code: 'panel-in-norm', by: 'machine', checked: r.checked });
          status = STATUS.OK;
          dest = DEST.NONE;
        } else {
          steps.push({ code: 'panel-out', by: 'machine', checked: r.checked, out: r.out });
          status = STATUS.OUT;
          dest = outOfNorm(steps);
        }
      }
    } else if (cell.kind === KIND.COMPLEX) {
      if (isBlank(reading.value)) {
        steps.push({ code: 'bad-value', by: 'machine' });
        status = STATUS.UNKNOWN;
        dest = DEST.UNDECIDED;
      } else {
        steps.push({ code: 'needs-analysis', by: 'machine' });
        status = STATUS.ANALYSIS;
        if (s.aiWorks) {
          steps.push({ code: 'ai-analyzes', by: 'ai' });
          steps.push({ code: 'complex-who-open', by: 'open', question: OPEN_QUESTION.COMPLEX_WHO });
          dest = DEST.AI;
        } else {
          steps.push({ code: 'ai-down-open', by: 'open', question: OPEN_QUESTION.AI_DOWN });
          dest = DEST.UNDECIDED;
        }
      }
    } else if (cell.kind === KIND.CAMERA) {
      const hasTrigger = Boolean(cell.triggers) && typeof reading.value === 'string'
        && Object.prototype.hasOwnProperty.call(cell.triggers, reading.value);
      const trigger = hasTrigger ? cell.triggers[reading.value] : undefined;
      if (trigger && trigger.action === 'ignore') {
        steps.push({ code: trigger.code, by: 'machine' });
        status = STATUS.IGNORED;
        dest = DEST.NONE;
      } else if (trigger && trigger.action === 'alarm') {
        // The camera triggers the automation, and the automation calls the doctor. No AI here.
        steps.push({ code: trigger.code, by: 'machine' });
        status = STATUS.OUT;
        dest = callDoctor(steps);
      } else {
        steps.push({ code: 'no-trigger', by: 'machine' });
        status = STATUS.UNKNOWN;
        dest = DEST.UNDECIDED;
      }
    } else if (cell.kind === KIND.SELF) {
      if (!checkSelf(cell, reading.value).valid) {
        steps.push({ code: 'bad-value', by: 'machine' });
        status = STATUS.UNKNOWN;
        dest = DEST.UNDECIDED;
      } else {
        steps.push({ code: 'recorded', by: 'machine' });
        if (cell.reviewByAi) {
          selfReports.push({ indicator: cell.indicator, value: reading.value, time });
          steps.push({ code: 'psych-review-later', by: 'machine' });
        } else {
          steps.push({ code: 'no-threshold', by: 'open' });
        }
        status = STATUS.RECORDED;
        dest = DEST.NONE;
      }
    } else {
      steps.push({ code: 'no-cell', by: 'machine' });
      status = STATUS.UNKNOWN;
      dest = DEST.UNDECIDED;
    }

    // Everything the machine could read goes into this person's history, in time order.
    if (cell && status !== STATUS.UNKNOWN) {
      const k = hkey(person.id, cell.indicator);
      if (!history.has(k)) history.set(k, []);
      const last = steps.find((x) => x.code === 'in-norm' || x.code === 'out-of-norm');
      const list = history.get(k);
      // The source is kept, so the screen can say where each value came from (a device, a person, made-up example data).
      // The red limit it crossed (or null) and the context (for example 'exercise') are kept for the screen and the levels.
      list.push({ time, value: reading.value, status, side: last ? last.side || null : null, percent: last ? last.percent : undefined, source: reading.source || null, example: Boolean(reading.example), red, context: reading.context || null, ...(last ? shiftOf(last) : {}) });
      list.sort((a, b) => a.time - b.time);
    }
    return entry(reading, cell, status, dest, steps, person.id, time);
  }

  // The team's periodic review: the AI looks at the self-reports collected since the last review.
  function review(personId, at = null) {
    const steps = [];
    const time = timeOf(at);
    if (!people.has(personId)) {
      steps.push({ code: 'no-person', by: 'machine' });
      return entry({ source: 'review', indicator: 'review', value: 0 }, null, STATUS.UNKNOWN, DEST.UNDECIDED, steps, null, time);
    }
    const count = pileOf(personId).length;
    let status;
    let dest;
    if (count === 0) {
      steps.push({ code: 'review-empty', by: 'machine' });
      status = STATUS.EMPTY;
      dest = DEST.NONE;
    } else if (s.aiWorks) {
      steps.push({ code: 'review-ai', by: 'ai', count });
      steps.push({ code: 'psych-rule-open', by: 'open', question: OPEN_QUESTION.PSYCH_RULE });
      status = STATUS.ANALYSIS;
      dest = DEST.AI;
      piles.set(personId, []);
    } else {
      steps.push({ code: 'ai-down-open', by: 'open', question: OPEN_QUESTION.AI_DOWN });
      status = STATUS.ANALYSIS;
      dest = DEST.UNDECIDED;
    }
    return entry({ source: 'review', indicator: 'review', value: count, person: personId }, null, status, dest, steps, personId, time);
  }

  return {
    receive,
    review,
    pendingReports(personId) {
      return pileOf(personId).length;
    },
    history(personId, indicator) {
      return (history.get(hkey(personId, indicator)) || []).map((x) => ({ ...x }));
    },
    crew() {
      return [...people.values()];
    },
    setState(patch) {
      Object.assign(s, patch);
      return { ...s };
    },
    getState() {
      return { ...s };
    },
  };
}
